    """Project edge-1 markers along complete rows/columns; recolor hit 2-components."""
    h, w = len(grid), len(grid[0])
    rows = {r for r in range(h) if grid[r][0] == 1 or grid[r][w-1] == 1}
    cols = {c for c in range(w) if grid[0][c] == 1 or grid[h-1][c] == 1}
    out = [row[:] for row in grid]
    # The trigger is a stroke crossing the interior of a 2-shape, not mere edge contact.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r,c) in seen:
                continue
            comp=[]; stack=[(r,c)]; seen.add((r,c))
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==2 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            minr=min(y for y,x in comp); maxr=max(y for y,x in comp)
            minc=min(x for y,x in comp); maxc=max(x for y,x in comp)
            crosses = any(y in rows and minc < x < maxc for y,x in comp)
            crosses |= any(x in cols and minr < y < maxr for y,x in comp)
            if crosses:
                for y,x in comp: out[y][x]=1
    for r in rows:
        for c in range(w): out[r][c]=1
    for c in cols:
        for r in range(h): out[r][c]=1
    return out
