    """Draw full marker-aligned 1 lines, then recolor contiguous 2-runs bracketed by 1s."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker_rows = {r for r in range(h) if grid[r][0] == 1 or grid[r][w - 1] == 1}
    marker_cols = {c for c in range(w) if grid[0][c] == 1 or grid[h - 1][c] == 1}
    for r in marker_rows:
        for c in range(w): out[r][c] = 1
    for c in marker_cols:
        for r in range(h): out[r][c] = 1
    # For each marked row/column, fill only 2 segments on that line that touch it;
    # line itself is a guide. Expand a touched segment to its connected 2-component.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen: continue
            comp=[]; stack=[(r,c)]; seen.add((r,c))
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
