    """Opposing edge 1 markers draw strokes; each 4-connected 2-object hit by a stroke turns 1."""
    h, w = len(grid), len(grid[0])
    rows = {r for r in range(h) if grid[r][0] == 1 and grid[r][w - 1] == 1}
    cols = {c for c in range(w) if grid[0][c] == 1 and grid[h - 1][c] == 1}
    out = [row[:] for row in grid]
